+// limitations under the License.
+
+package promql
+
+import (
+	"cmp"
+	"math/big"
+	"net/netip"
+	"slices"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+
+	"github.com/facette/natsort"
+	"github.com/grafana/regexp"
+	"golang.org/x/mod/semver"
+)
+
+type labelSortClass uint8
+
+const (
+	labelWhitespace labelSortClass = iota
+	labelPositiveInfinity
+	labelNumber
+	labelNegativeInfinity
+	labelDuration
+	labelBytes
+	labelVersion
+	labelIP
+	labelCIDR
+	labelTimestamp
+	labelNatural
+)
+
+type labelSortValue struct {
+	class     labelSortClass
+	magnitude labelMagnitude
+	version   string
+	address   netip.Addr
+	prefix    int
+	timestamp time.Time
+}
+
+// Each value is classified independently, so mixed domains have a transitive
+// order. Comparing only domains that both strings happen to parse as would not
+// establish a total order.
+func compareLabelValues(a, b string) int {
+	if a == b {
+		return 0
+	}
+	x, y := parseLabelSortValue(a), parseLabelSortValue(b)
+	if c := cmp.Compare(x.class, y.class); c != 0 {
+		return c
+	}
+	var c int
+	switch x.class {
+	case labelNumber, labelDuration, labelBytes:
+		c = x.magnitude.compare(y.magnitude)
+	case labelVersion:
+		c = semver.Compare(x.version, y.version)
+	case labelIP, labelCIDR:
+		// Addr.Compare orders IPv4 before IPv6 without unmapping IPv6 literals.
+		c = x.address.Compare(y.address)
+		if c == 0 && x.class == labelCIDR {
+			c = cmp.Compare(x.prefix, y.prefix)
+		}
+	case labelTimestamp:
+		c = x.timestamp.Compare(y.timestamp)
+	}
+	if c != 0 {
+		return c
+	}
+	// natsort can report both directions as less for equivalent digit runs
+	// such as "01" and "1". Resolve those natural ties lexically.
+	less, greater := natsort.Compare(a, b), natsort.Compare(b, a)
+	if less != greater {
+		if less {
+			return -1
+		}
+		return 1
+	}
+	return strings.Compare(a, b)
+}
+
+var (
+	labelNumberRE       = regexp.MustCompile(`^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?`)
+	labelDurationUnitRE = regexp.MustCompile(`^(ns|us|µs|μs|ms|s|m|h|d|w|y)`)
+	// semver accepts abbreviated versions as well. Labels require all three
+	// components; semver.IsValid validates identifiers and leading zeroes.
+	labelVersionRE = regexp.MustCompile(`^v?[0-9]+\.[0-9]+\.[0-9]+(?:[-+].*)?$`)
+)
+
+var labelDurationUnits = map[string]int64{
+	"ns": 1, "us": 1000, "µs": 1000, "μs": 1000, "ms": 1000000,
+	"s": 1000000000, "m": 60 * 1000000000, "h": 3600 * 1000000000,
+	"d": 86400 * 1000000000, "w": 7 * 86400 * 1000000000, "y": 365 * 86400 * 1000000000,
+}
+
+var labelByteUnits = map[string]int64{
+	"B":  1,
+	"kB": 1000, "KB": 1000, "MB": 1000000, "GB": 1000000000,
+	"TB": 1000000000000, "PB": 1000000000000000, "EB": 1000000000000000000,
+	"KiB": 1 << 10, "MiB": 1 << 20, "GiB": 1 << 30,
+	"TiB": 1 << 40, "PiB": 1 << 50, "EiB": 1 << 60,
+}
+
+func parseLabelSortValue(s string) labelSortValue {
+	first, _ := utf8.DecodeRuneInString(s)
+	if unicode.IsSpace(first) {
+		return labelSortValue{class: labelWhitespace}
+	}
+	switch strings.ToLower(s) {
+	case "inf", "+inf", "infinity", "+infinity":
+		return labelSortValue{class: labelPositiveInfinity}
+	case "-inf", "-infinity":
+		return labelSortValue{class: labelNegativeInfinity}
+	}
+	if number := labelNumberRE.FindString(s); number != "" {
+		if len(number) == len(s) {
+			return labelSortValue{class: labelNumber, magnitude: labelMagnitude{parseLabelDecimal(number, 1)}}
+		}
+		if magnitude, ok := parseLabelDuration(s); ok {
+			return labelSortValue{class: labelDuration, magnitude: magnitude}
+		}
+		if unit, ok := labelByteUnits[strings.TrimLeft(s[len(number):], " ")]; ok {
+			return labelSortValue{class: labelBytes, magnitude: labelMagnitude{parseLabelDecimal(number, unit)}}
+		}
+	}
+	if labelVersionRE.MatchString(s) {
+		v := s
+		if v[0] != 'v' {
+			v = "v" + v
+		}
+		if semver.IsValid(v) {
+			return labelSortValue{class: labelVersion, version: v}
+		}
+	}
+	if ip, err := netip.ParseAddr(s); err == nil {
+		return labelSortValue{class: labelIP, address: ip}
+	}
+	if prefix, err := netip.ParsePrefix(s); err == nil {
+		return labelSortValue{class: labelCIDR, address: prefix.Masked().Addr(), prefix: prefix.Bits()}
+	}
+	if timestamp, err := time.Parse(time.RFC3339Nano, s); err == nil {
+		return labelSortValue{class: labelTimestamp, timestamp: timestamp}
+	}
+	return labelSortValue{class: labelNatural}
+}
+
+func parseLabelDuration(s string) (labelMagnitude, bool) {
+	var result labelMagnitude
+	sign := int64(1)
+	if s[0] == '-' || s[0] == '+' {
+		if s[0] == '-' {
+			sign = -1
+		}
+		s = s[1:]
+	}
+	for s != "" {
+		// A leading sign applies to the entire compound duration.
+		if s[0] == '+' || s[0] == '-' {
+			return nil, false
+		}
+		number := labelNumberRE.FindString(s)
+		if number == "" {
+			return nil, false
+		}
+		s = s[len(number):]
+		unit := labelDurationUnitRE.FindString(s)
+		if unit == "" {
+			return nil, false
+		}
+		result = append(result, parseLabelDecimal(number, sign*labelDurationUnits[unit]))
+		s = s[len(unit):]
+	}
+	return result, len(result) != 0
+}
+
+// Store decimals as coefficient * 10^exponent. Both integers are unbounded;
+// neither floating point rounding nor enormous powers of ten are needed.
+// A compound duration is a sum of these terms.
+type labelDecimal struct {
+	coefficient *big.Int
+	exponent    *big.Int
+}
+
+type labelMagnitude []labelDecimal
+
+func parseLabelDecimal(s string, multiplier int64) labelDecimal {
+	exponent := new(big.Int)
+	if i := strings.IndexAny(s, "eE"); i >= 0 {
+		exponent.SetString(s[i+1:], 10)
+		s = s[:i]
+	}
+	if i := strings.IndexByte(s, '.'); i >= 0 {
+		exponent.Sub(exponent, big.NewInt(int64(len(s)-i-1)))
+		s = s[:i] + s[i+1:]
+	}
+	coefficient, _ := new(big.Int).SetString(s, 10)
+	coefficient.Mul(coefficient, big.NewInt(multiplier))
+	return labelDecimal{coefficient: coefficient, exponent: exponent}
+}
+
+func (a labelMagnitude) compare(b labelMagnitude) int {
+	terms := make(labelMagnitude, 0, len(a)+len(b))
+	terms = append(terms, a...)
+	for _, term := range b {
+		terms = append(terms, labelDecimal{coefficient: new(big.Int).Neg(term.coefficient), exponent: term.exponent})
+	}
+	slices.SortFunc(terms, func(a, b labelDecimal) int { return b.exponent.Cmp(a.exponent) })
+	remaining := new(big.Int)
+	for _, term := range terms {
+		remaining.Add(remaining, new(big.Int).Abs(term.coefficient))
+	}
+	sum := new(big.Int)
+	previous := terms[0].exponent
+	for _, term := range terms {
+		gap := new(big.Int).Sub(previous, term.exponent)
+		if sum.Sign() != 0 {
+			// Every remaining exponent is at most this term's exponent. If
+			// the accumulated sum dominates their absolute coefficients, its
+			// sign is final. This also bounds allocations for huge exponents.
+			if gap.Cmp(big.NewInt(int64(len(remaining.String())))) >= 0 {
+				return sum.Sign()
+			}
+			sum.Mul(sum, new(big.Int).Exp(big.NewInt(10), gap, nil))
+		}
+		sum.Add(sum, term.coefficient)
+		remaining.Sub(remaining, new(big.Int).Abs(term.coefficient))
+		previous = term.exponent
+	}
+	return sum.Sign()
+}
