+
+func TestCompareLabelValues(t *testing.T) {
+	for name, ordered := range map[string][]string{
+		"domains":              {" 2", " 10", "+Inf", "-2", "0", "+1e3", "-Inf", "-1s", "1s", "-1B", "1B", "v1.2.3", "127.0.0.1", "::1", "10.0.0.0/8", "::/0", "2024-01-01T00:00:00Z", "", "NaN", "item2", "item10"},
+		"natural numeric ties": {" 01", " 1", "01", "1", "host01", "host1"},
+		"numbers":              {"-1e1000", "-9007199254740993", "-9007199254740992", "-1.1", "-.1", "0", "1e-1000", "+.2", "1.", "1.000000000000000000000000000001", "1.01", "+2E+2", "9007199254740992", "9007199254740993", "1e1000"},
+		"durations":            {"-1e1000h", "-1h30m", "-1h", "-1e-1000ns", "0s", "+1e-1000ns", "1ns", "1us", "1ms", "+1.2e1s", "1m", "1h", "1h1ns", "1h30m", "1d", "1w", "1y", "1e1000h"},
+		"bytes":                {"-1e1000GiB", "-1KiB", "-1e-1000B", "0B", "1e-1000B", "1B", "+1e3B", "1KiB", "1MB", "1MiB", "1GB", "1GiB", "1TB", "1TiB", "1PB", "1PiB", "1EB", "1EiB", "1e1000GiB"},
+		"versions":             {"v1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta", "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0", "v2.0.0", "10.0.0", "999999999999999999999999999999.0.0"},
+		"addresses":            {"0.0.0.0", "10.0.0.2", "10.0.0.10", "255.255.255.255", "::", "::1", "::2", "::a", "::ffff:0.0.0.0", "2001:db8::1"},
+		"prefixes":             {"0.0.0.0/0", "10.0.0.0/8", "10.0.0.0/16", "10.0.1.0/24", "255.255.255.255/32", "::/0", "::/64", "::1/128", "::ffff:0.0.0.0/96", "2001:db8::/32"},
+		"timestamps":           {"2023-12-31T23:59:59Z", "2024-01-01T01:00:00+01:00", "2024-01-01T00:00:00.000000001Z", "2024-01-01T00:00:00-01:00"},
+		"unbounded exponents":  {"-1e99999999999999999999999", "-1e99999999999999999999998", "0", "1e-99999999999999999999999", "1e-99999999999999999999998", "1e99999999999999999999998", "1e99999999999999999999999"},
+		"unbounded durations":  {"1e99999999999999999999998h", "1e99999999999999999999999h", "1e99999999999999999999999h1ns", "1e99999999999999999999999h2ns"},
+		"unbounded bytes":      {"1e99999999999999999999999B", "1e99999999999999999999999kB", "1e99999999999999999999999KiB"},
+	} {
+		t.Run(name, func(t *testing.T) {
+			// All pairs check transitivity as well as adjacent boundaries and
+			// antisymmetry, independent of the input permutation.
+			for i, a := range ordered {
+				require.Zero(t, compareLabelValues(a, a))
+				for _, b := range ordered[i+1:] {
+					require.Negative(t, compareLabelValues(a, b), "%q < %q", a, b)
+					require.Positive(t, compareLabelValues(b, a), "%q > %q", b, a)
+				}
+			}
+		})
+	}
+}
+
+func TestLabelSortNaturalFallback(t *testing.T) {
+	invalid := []string{
+		"", "NaN", "nan", "+NaN", "-NaN", "1e", "1e+", "1E-", "+", ".", "1_000", "0x10", "1/2",
+		"1es", "1e+B", "1e-GB", "1h-2m", "1m2", "1XB", "1s ",
+		"v1", "v1.2", "01.2.3", "1.02.3", "1.2.03", "1.2.3.999", "1.2.3-01", "1.2.3-", "1.2.3+", "1.2.3-a..b",
+		"256.0.0.1", "1.2.3.4/33", "::/129", "2024-02-30T00:00:00Z", "item2", "item10",
+	}
+	for _, s := range invalid {
+		require.Equal(t, labelNatural, parseLabelSortValue(s).class, "%q must be untyped", s)
+	}
+	want := slices.Clone(invalid)
+	slices.SortFunc(want, func(a, b string) int {
+		less, greater := natsort.Compare(a, b), natsort.Compare(b, a)
+		if less == greater {
+			return strings.Compare(a, b)
+		}
+		if less {
+			return -1
+		}
+		return 1
+	})
+	slices.SortFunc(invalid, compareLabelValues)
+	require.Equal(t, want, invalid)
+}
+
+func TestLabelSortNaturalTies(t *testing.T) {
+	for _, equal := range [][]string{
+		{"+Inf", "Inf", "Infinity", "inf"},
+		{"-Inf", "-Infinity", "-inf"},
+		{"+1", "01", "1", "1.0", "1e0"},
+		{"+0", "-0", "0", "0e99999999999999999999999"},
+		{"60s", "1m", "+1m", "0.5m30s", "6e1s"},
+		{"-60s", "-1m", "-0.5m30s"},
+		{"1024B", "1KiB", "1.024kB", "+1.024e3B", "1024 B"},
+		{"1.2.3", "v1.2.3", "1.2.3+build.2", "1.2.3+build.10"},
+		{"::1", "0:0:0:0:0:0:0:1"},
+		{"10.0.0.1/8", "10.0.0.0/8", "10.2.3.4/8"},
+		{"2024-01-01T00:00:00Z", "2024-01-01T00:00:00.000Z", "2024-01-01T01:00:00+01:00"},
+		{" 10", " 2", "\t1s", "\n1.2.3", "\u00a01", "\u20031KiB"},
+	} {
+		for _, a := range equal {
+			for _, b := range equal {
+				less := natsort.Compare(a, b)
+				if less == natsort.Compare(b, a) {
+					less = a < b
+				}
+				require.Equal(t, less, compareLabelValues(a, b) < 0, "%q versus %q", a, b)
+				require.Equal(t, compareLabelValues(a, b), -compareLabelValues(b, a), "%q versus %q", a, b)
+			}
+		}
+	}
+	for _, s := range []string{"\t1", "\n+Inf", " 1s", "\r1B", "\u00a0v1.2.3", "\u2003::1", " 10.0.0.0/8", " 2024-01-01T00:00:00Z", " "} {
+		require.Equal(t, labelWhitespace, parseLabelSortValue(s).class)
+		require.Negative(t, compareLabelValues(s, "+Inf"))
+	}
+}
+
+func TestLabelMagnitudeExactComparison(t *testing.T) {
+	// Check the sparse decimal arithmetic against independent rational
+	// arithmetic, including cancellation and overlapping compound terms.
+	rng := rand.New(rand.NewSource(1))
+	for range 1000 {
+		var values [2]labelMagnitude
+		rats := [2]*big.Rat{new(big.Rat), new(big.Rat)}
+		for i := range values {
+			for range 1 + rng.Intn(6) {
+				coefficient, exponent := rng.Int63n(2000001)-1000000, rng.Intn(101)-50
+				s := strconv.FormatInt(coefficient, 10) + "e" + strconv.Itoa(exponent)
+				values[i] = append(values[i], parseLabelDecimal(s, 1))
+				r, ok := new(big.Rat).SetString(s)
+				require.True(t, ok)
+				rats[i].Add(rats[i], r)
+			}
+		}
+		require.Equal(t, rats[0].Cmp(rats[1]), values[0].compare(values[1]))
+	}
+}
+
+func TestSortByLabelTyped(t *testing.T) {
+	ordered := []string{" 02", " 2", " 10", "+Inf", "-10", "+2", "02", "2", "10", "-Inf", "1s", "1B", "v1.2.3", "10.0.0.1", "::1", "10.0.0.0/8", "2024-01-01T00:00:00Z", "", "NaN", "host2", "host10"}
+	var want Vector
+	for _, value := range ordered {
+		for _, secondary := range []string{"2", "10"} {
+			for _, id := range []string{"a", "b"} {
+				want = append(want, Sample{Metric: labels.FromStrings("value", value, "secondary", secondary, "id", id), F: 1})
+			}
+		}
+	}
+	// Both sample types must participate in the same order.
+	want[0].H = &histogram.FloatHistogram{}
+	args := parser.Expressions{nil, &parser.StringLiteral{Val: "value"}, &parser.StringLiteral{Val: "secondary"}}
+	for _, descending := range []bool{false, true} {
+		expected := slices.Clone(want)
+		if descending {
+			slices.Reverse(expected)
+		}
+		for seed := range int64(10) {
+			input := slices.Clone(want)
+			rand.New(rand.NewSource(seed)).Shuffle(len(input), func(i, j int) { input[i], input[j] = input[j], input[i] })
+			fn := funcSortByLabel
+			if descending {
+				fn = funcSortByLabelDesc
+			}
+			got, annotations := fn([]Vector{input}, nil, args, nil)
+			require.Empty(t, annotations)
